arguments.command:
cat > /tmp/analyze.rb <<'EOF'
require 'json'
path = ARGV[0]
top = (ARGV[1] || 25).to_i
d = JSON.parse(File.read(path))
s = d['summary']
puts "examples=#{d['examples'].size} failures=#{s['failure_count']} pending=#{s['pending_count']} duration=#{s['duration'].round(2)}s load=#{s['load_time'].round(2)}s"
by_file = d['examples'].group_by { |e| e['file_path'] }.map { |f, es| [f, es.sum { |e| e['run_time'] }, es.size] }.sort_by { |x| -x[1] }
puts "\n== per-file (top #{top})"
by_file.first(top).each { |f, t, n| printf("%8.2f s  %4d ex  %s\n", t, n, f) }
rt = d['examples'].map { |e| e['run_time'] }.sort
pct = ->(p) { rt[(p * (rt.size - 1)).round] }
printf("\nper-example: median %.1f ms p90 %.1f ms p99 %.1f ms max %.2f s min %.2f ms\n", pct.(0.5)*1000, pct.(0.9)*1000, pct.(0.99)*1000, rt.last, rt.first*1000)
puts "\n== slowest examples (top #{top})"
d['examples'].sort_by { |e| -e['run_time'] }.first(top).each { |e| printf("%7.2f s  %s\n", e['run_time'], e['full_description'][0,140]) }
puts "\n== sum of time by top-level describe/type"
by_type = d['examples'].group_by { |e| e['file_path'].sub(%r{^\./}, '').split('/')[1..2].join('/') }.map { |k, es| [k, es.sum { |e| e['run_time'] }, es.size] }.sort_by { |x| -x[1] }
by_type.first(top).each { |k, t, n| printf("%8.2f s  %4d ex  %s\n", t, n, k) }
EOF
ruby /tmp/analyze.rb /tmp/req_orig_4242.json 30

