arguments.command:
cd /tmp && timeout 900 ruby -e '
dump = Marshal.load(File.binread("/tmp/req_p2b_cpu.dump")); frames = dump[:frames]; raw = dump[:raw]
total = 0; mailers = Hash.new(0); triggers = Hash.new(0); i = 0
while i < raw.size
  len = raw[i]; stack = raw[i+1, len]; count = raw[i+1+len]; i += len + 2; total += count
  next unless stack.any? { |f| frames[f][:name] == "ActionMailer::MailDeliveryJob#perform" }
  mid = stack.find { |f| frames[f][:name] =~ /Mailer#|Mailer\./ && frames[f][:file].to_s =~ /app\/mailers/ }
  mailers[mid ? frames[mid][:name] : "(none)"] += count
  app = stack.select { |f| frames[f][:file].to_s.start_with?("/app/app") }.map { |f| frames[f][:name] }
  trig = app.find { |n| n =~ /NotifyService|Devise|Confirmable|send_|Notifications|User|Account|Status/ }
  triggers[trig.to_s] += count
end
printf("MailDeliveryJob total: %.2f%%\n", 100.0 * mailers.values.sum / total)
mailers.sort_by { |_, c| -c }.first(10).each { |k, c| printf("%6.2f%%  %s\n", 100.0*c/total, k) }
puts "-- nearest app frame"
triggers.sort_by { |_, c| -c }.first(10).each { |k, c| printf("%6.2f%%  %s\n", 100.0*c/total, k) }
' ; grep -n "deliver_later\|deliver_now\|send_email\|Mailer" /app/app/services/notify_service.rb | head

